import {readFile} from 'node:fs/promises';import {validateConfig,validateCatalogue,readPublicJson} from '../../catalogue.mjs';
const config=validateConfig(JSON.parse(await readFile('config.json','utf8')));
try{const response=await fetch(config.apiOrigin+'/v1/public/catalogue',{headers:{accept:'application/json',origin:'https://brownnoodyai-sketch.github.io'},redirect:'error',signal:AbortSignal.timeout(15000)});if(!response.ok)console.log(JSON.stringify({catalogueReachable:false,httpStatus:response.status}));else{const c=validateCatalogue(await readPublicJson(response));console.log(JSON.stringify({catalogueReachable:true,services:c.items.filter(i=>i.kind==='SERVICE').length,products:c.items.filter(i=>i.kind==='PRODUCT').length,cors:response.headers.get('access-control-allow-origin')}));}}catch(e){console.log(JSON.stringify({catalogueReachable:false,error:e.name}));}
